// Mail in ein einheitliches, sauberes Format bringen
const out = [];
for (const item of $input.all()) {
  const m = item.json;
  const fromText = typeof m.from === 'string' ? m.from : (m.from?.text || '');
  const fromAddr = (typeof m.from === 'object' && m.from?.value?.[0]?.address)
    || ((fromText.match(/<([^>]+)>/) || [null, fromText])[1] || '');

  let text = m.text || m.textPlain || '';
  if (!text.trim()) {                       // reine HTML-Mail -> Text extrahieren
    const html = m.html || m.textHtml || '';
    text = html.replace(/<style[\s\S]*?<\/style>/gi, ' ')
               .replace(/<br\s*\/?>/gi, '\n').replace(/<\/p>/gi, '\n')
               .replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ');
  }
  // Zitierten Verlauf (alte Mails) abschneiden
  const cut = text.search(/\n\s*(Am .{5,120}schrieb.{0,120}:|On .{5,120}wrote:|-{3,}\s*Original)/);
  if (cut > 0) text = text.slice(0, cut);

  const hdr = m.headers || m.metadata || {};
  out.push({ json: {
    absender: fromText,
    absender_email: fromAddr.trim().toLowerCase(),
    betreff: m.subject || '',
    inhalt: text.replace(/\n{3,}/g, '\n\n').trim(),
    datum: m.date ? new Date(m.date).toLocaleString('de-DE', { timeZone: 'Europe/Berlin' }) : '',
    message_id: m.messageId || hdr['message-id'] || '',
    auto_submitted: String(hdr['auto-submitted'] || '').toLowerCase(),
  }});
}
return out;
